  "user_id" uuid NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'draft',
  "attempt" integer NOT NULL DEFAULT 1,
  "full_name" varchar(120),
  "phone" varchar(40),
  "city" varchar(80),
  "state" varchar(80),
  "qualification" varchar(32),
  "has_telecalling_experience" boolean,
  "experience_years" integer,
  "previous_company" varchar(160),
  "languages" varchar(300),
  "employment_preference" varchar(32),
  "additional_info" text,
  "confirmed_adult" boolean NOT NULL DEFAULT false,
  "consented_privacy" boolean NOT NULL DEFAULT false,
  "consented_at" timestamptz(3),
  "feedback" text,
  "admin_notes" text,
  "submitted_at" timestamptz(3),
  "decided_at" timestamptz(3),
  "decided_by" uuid,
  "version" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "telecaller_applications_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_telecaller_applications_status" CHECK ("status" IN ('draft', 'pending', 'more_info_requested', 'approved', 'rejected')),
  CONSTRAINT "ck_telecaller_applications_qualification" CHECK ("qualification" IN ('high_school', 'diploma', 'bachelor', 'master', 'doctorate', 'other')),
  CONSTRAINT "ck_telecaller_applications_employment_preference" CHECK ("employment_preference" IN ('full_time', 'part_time'))
);

CREATE TABLE "telecaller_profiles" (
  "user_id" uuid NOT NULL,
  "application_id" uuid,
  "status" varchar(32) NOT NULL DEFAULT 'active',
  "approved_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "approved_by" uuid,
  "status_changed_at" timestamptz(3),
  "status_changed_by" uuid,
  "status_reason" varchar(300),
  "version" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "telecaller_profiles_pkey" PRIMARY KEY ("user_id"),
  CONSTRAINT "ck_telecaller_profiles_status" CHECK ("status" IN ('active', 'inactive'))
);

CREATE TABLE "telecaller_resumes" (
  "id" uuid NOT NULL,
  "application_id" uuid NOT NULL,
  "attempt" integer NOT NULL,
  "original_filename" varchar(200) NOT NULL,
  "mime_type" varchar(100) NOT NULL,
  "size_bytes" integer NOT NULL,
  "sha256" char(64) NOT NULL,
  "data" bytea NOT NULL,
  "uploaded_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "telecaller_resumes_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "videos" (
  "id" uuid NOT NULL,
  "group_name" varchar(255),
  "title" varchar(255),
  "thumb" varchar(255),
  "video" varchar(255),
  "video_length" real,
  "is_preview" boolean DEFAULT false,
  "short_id" integer NOT NULL DEFAULT 0,
  "assets_zip" varchar(255),
  "userId" uuid NOT NULL,
  "courseId" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "videos_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "book_orders" (
  "id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "book_id" uuid NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'pending',
  "amount_cents" integer NOT NULL,
  "currency" char(3) NOT NULL DEFAULT 'inr',
  "payment_method" varchar(32) NOT NULL DEFAULT 'card',
  "stripe_charge_id" varchar(80),
  "access_key" varchar(80),
  "failure_reason" varchar(80),
  "paid_at" timestamptz,
  "refunded_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "book_orders_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_book_orders_status" CHECK ("status" IN ('pending', 'paid', 'failed', 'refunded')),
  CONSTRAINT "ck_book_orders_payment_method" CHECK ("payment_method" IN ('card', 'free', 'grant'))
);

CREATE TABLE "book_progress" (
  "id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "book_id" uuid NOT NULL,
  "position" integer NOT NULL DEFAULT 1,
  "total_pages" integer NOT NULL DEFAULT 1,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "book_progress_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "course_assets" (
  "id" uuid NOT NULL,
  "lecture_name" varchar(255),
  "lecture_file" varchar(255),
  "courseId" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "course_assets_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "course_progresses" (
  "id" uuid NOT NULL,
  "finished" boolean DEFAULT true,
  "userId" uuid NOT NULL,
  "courseId" uuid NOT NULL,
  "videoId" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "course_progresses_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "fam_devices" (
  "id" uuid NOT NULL,
  "owner_user_id" uuid NOT NULL,
  "pairing_code_id" uuid NOT NULL,
  "name" varchar(60),
  "label" varchar(80) NOT NULL DEFAULT 'Device',
  "secret_hash" varchar(64) NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'pending',
  "pending_until" timestamptz NOT NULL,
  "approved_at" timestamptz,
  "approved_by" uuid,
  "revoked_at" timestamptz,
  "revoked_by" uuid,
  "last_seen_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fam_devices_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_fam_devices_status" CHECK ("status" IN ('pending', 'approved', 'denied', 'revoked'))
);

CREATE TABLE "fam_link_codes" (
  "id" uuid NOT NULL,
  "learner_id" uuid NOT NULL,
  "issued_by" uuid NOT NULL,
  "code_hash" varchar(64),
  "status" varchar(32) NOT NULL DEFAULT 'open',
  "expires_at" timestamptz NOT NULL,
  "used_by" uuid,
  "used_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "requested_by" uuid,
  CONSTRAINT "fam_link_codes_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_fam_link_codes_status" CHECK ("status" IN ('open', 'used', 'cancelled', 'replaced'))
);

CREATE TABLE "instructor_application_events" (
  "id" uuid NOT NULL,
  "application_id" uuid NOT NULL,
  "from_status" varchar(24),
  "to_status" varchar(24) NOT NULL,
  "actor" varchar(12) NOT NULL,
  "actor_user_id" uuid,
  "feedback" text,
  "internal_note" text,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "instructor_application_events_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "lc_attendance" (
  "id" uuid NOT NULL,
  "class_id" uuid NOT NULL,
  "participant_key" varchar(64) NOT NULL,
  "display_name" varchar(120) NOT NULL,
  "status" varchar(32) NOT NULL DEFAULT 'present',
  "source" varchar(32) NOT NULL DEFAULT 'auto',
  "first_joined_at" timestamptz(3),
  "last_seen_at" timestamptz(3),
  "left_at" timestamptz(3),
  "total_seconds" integer NOT NULL DEFAULT 0,
  "note" varchar(300),
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "lc_attendance_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_lc_attendance_status" CHECK ("status" IN ('present', 'late', 'absent', 'excused')),
  CONSTRAINT "ck_lc_attendance_source" CHECK ("source" IN ('auto', 'instructor'))
);

CREATE TABLE "lc_audit_logs" (
  "id" uuid NOT NULL,
  "class_id" uuid,
  "actor_user_id" uuid,
  "action" varchar(64) NOT NULL,
  "details" jsonb,
  "ip" varchar(64),
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "lc_audit_logs_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "lc_enrolments" (
  "id" uuid NOT NULL,
  "class_id" uuid NOT NULL,
  "participant_key" varchar(64) NOT NULL,
  "user_id" uuid,
  "learner_id" uuid,
  "display_name" varchar(120) NOT NULL,
  "added_by" uuid,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "lc_enrolments_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "lc_quiz_sessions" (
  "id" uuid NOT NULL,
  "class_id" uuid NOT NULL,
  "title" varchar(160) NOT NULL,
  "source_quiz_id" uuid,
  "status" varchar(32) NOT NULL DEFAULT 'open',
  "created_by" uuid,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "lc_quiz_sessions_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_lc_quiz_sessions_status" CHECK ("status" IN ('open', 'ended'))
