CREATE TABLE "live_question_responses" (
  "id" uuid NOT NULL,
  "live_question_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "option_id" varchar(16) NOT NULL,
  "is_correct" boolean NOT NULL,
  "submitted_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "live_question_responses_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "meeting_call_logs" (
  "id" uuid NOT NULL,
  "meeting_request_id" uuid NOT NULL,
  "telecaller_user_id" uuid,
  "telecaller_name" varchar(120) NOT NULL,
  "called_at" timestamptz(3) NOT NULL,
  "answered" boolean NOT NULL,
  "outcome" varchar(32) NOT NULL,
  "interest" varchar(32),
  "follow_up_status_after" varchar(32),
  "notes" text NOT NULL,
  "next_follow_up_at" timestamptz(3),
  "confirmation_details" text,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "meeting_call_logs_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_meeting_call_logs_outcome" CHECK ("outcome" IN ('spoke_to_customer', 'no_answer', 'busy', 'voicemail_left', 'wrong_number', 'call_back_requested', 'other')),
  CONSTRAINT "ck_meeting_call_logs_interest" CHECK ("interest" IN ('high', 'medium', 'low', 'none')),
  CONSTRAINT "ck_meeting_call_logs_follow_up_status_after" CHECK ("follow_up_status_after" IN ('not_contacted', 'contacted', 'follow_up_required', 'meeting_confirmed', 'not_interested', 'unable_to_reach', 'completed'))
);

CREATE TABLE "meeting_followup_events" (
  "id" uuid NOT NULL,
  "meeting_request_id" uuid NOT NULL,
  "event_type" varchar(32) NOT NULL,
  "actor_user_id" uuid,
  "actor_name" varchar(120) NOT NULL,
  "actor_role" varchar(32) NOT NULL,
  "from_user_id" uuid,
  "from_name" varchar(120),
  "to_user_id" uuid,
  "to_name" varchar(120),
  "from_status" varchar(24),
  "to_status" varchar(24),
  "reason" varchar(500),
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "meeting_followup_events_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_meeting_followup_events_event_type" CHECK ("event_type" IN ('take', 'transfer', 'admin_assign', 'admin_clear', 'status_change', 'completed')),
  CONSTRAINT "ck_meeting_followup_events_actor_role" CHECK ("actor_role" IN ('telecaller', 'admin'))
);

CREATE TABLE "meeting_followups" (
  "meeting_request_id" uuid NOT NULL,
  "follow_up_status" varchar(32) NOT NULL DEFAULT 'not_contacted',
  "owner_user_id" uuid,
  "owned_at" timestamptz(3),
  "last_contacted_at" timestamptz(3),
  "next_follow_up_at" timestamptz(3),
  "completed_at" timestamptz(3),
  "completed_by" uuid,
  "completion_note" varchar(500),
  "version" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  "updated_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "meeting_followups_pkey" PRIMARY KEY ("meeting_request_id"),
  CONSTRAINT "ck_meeting_followups_follow_up_status" CHECK ("follow_up_status" IN ('not_contacted', 'contacted', 'follow_up_required', 'meeting_confirmed', 'not_interested', 'unable_to_reach', 'completed'))
);

CREATE TABLE "meeting_request_events" (
  "id" uuid NOT NULL,
  "meeting_request_id" uuid NOT NULL,
  "from_status" varchar(24),
  "to_status" varchar(24) NOT NULL,
  "actor" varchar(20) NOT NULL,
  "actor_user_id" uuid,
  "note" varchar(500),
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "meeting_request_events_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ml_assignment_targets" (
  "id" uuid NOT NULL,
  "assignment_id" uuid NOT NULL,
  "learner_id" uuid NOT NULL,
  "started_at" timestamptz,
  "attempt_id" uuid,
  "completed_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ml_assignment_targets_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ml_attempts" (
  "id" uuid NOT NULL,
  "learner_id" uuid NOT NULL,
  "client_attempt_id" varchar(64) NOT NULL,
  "session_id" varchar(64),
  "subject" varchar(16) NOT NULL,
  "level_id" varchar(8) NOT NULL,
  "set_id" varchar(12) NOT NULL,
  "worksheet_no" integer NOT NULL,
  "variant" integer NOT NULL DEFAULT 0,
  "seed" varchar(80) NOT NULL,
  "total" integer NOT NULL,
  "correct_first" integer NOT NULL,
  "accuracy" real NOT NULL,
  "duration_ms" integer NOT NULL,
  "target_seconds" integer NOT NULL,
  "stars" integer NOT NULL DEFAULT 0,
  "status" varchar(16) NOT NULL,
  "outcome" varchar(24) NOT NULL,
  "counted" boolean NOT NULL DEFAULT false,
  "hints_used" integer NOT NULL DEFAULT 0,
  "responses" jsonb,
  "started_at" timestamptz NOT NULL,
  "completed_at" timestamptz NOT NULL,
  "local_date" date NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ml_attempts_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ml_daily_activity" (
  "id" uuid NOT NULL,
  "learner_id" uuid NOT NULL,
  "local_date" date NOT NULL,
  "worksheets" integer NOT NULL DEFAULT 0,
  "stars" integer NOT NULL DEFAULT 0,
  "seconds" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ml_daily_activity_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ml_hint_events" (
  "id" uuid NOT NULL,
  "learner_id" uuid NOT NULL,
  "session_id" varchar(64) NOT NULL,
  "question_index" integer NOT NULL,
  "mode" varchar(16) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ml_hint_events_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ml_learner_guardians" (
  "id" uuid NOT NULL,
  "learner_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "relation" varchar(32) NOT NULL,
  "created_by" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ml_learner_guardians_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_ml_learner_guardians_relation" CHECK ("relation" IN ('parent', 'instructor'))
