CREATE TABLE "questions" (
  "id" uuid NOT NULL,
  "question_text" text,
  "quizId" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "questions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "telecaller_application_events" (
  "id" uuid NOT NULL,
  "application_id" uuid NOT NULL,
  "attempt" integer NOT NULL DEFAULT 1,
  "from_status" varchar(24),
  "to_status" varchar(24) NOT NULL,
  "actor" varchar(32) NOT NULL,
  "actor_user_id" uuid,
  "feedback" text,
  "internal_note" text,
  "form_snapshot" jsonb,
  "email_status" varchar(32) NOT NULL DEFAULT 'none',
  "created_at" timestamptz(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT "telecaller_application_events_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "ck_telecaller_application_events_actor" CHECK ("actor" IN ('applicant', 'admin', 'system')),
  CONSTRAINT "ck_telecaller_application_events_email_status" CHECK ("email_status" IN ('none', 'sent', 'skipped', 'failed'))
);

CREATE TABLE "user_responses" (
